#!/usr/bin/env python3
import hashlib
import json
import re
from pathlib import Path

PRIVATE = Path('/tmp/cnm-pierce34/private')
MANIFEST = Path('.cs/epics/001-o-offline-commit-flow/artifacts/034/shadow-manifest.json')
TOKEN_RE = re.compile(r'[A-Za-z0-9_]+|[^\s]')


def sha(value: bytes | str) -> str:
    if isinstance(value, str):
        value = value.encode('utf-8')
    return hashlib.sha256(value).hexdigest()


def compact(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'))


def normalize_patch(patch: str) -> str:
    changed = []
    in_hunk = False
    for line in patch.splitlines():
        if line.startswith('diff --git '):
            in_hunk = False
        elif line.startswith('@@'):
            in_hunk = True
        elif in_hunk and line[:1] in {'+', '-'}:
            changed.append(re.sub(r'\s+', ' ', line[1:].strip()).lower())
    return '\n'.join(changed)


def normalize_target(target: str) -> str:
    return re.sub(r'\s+', ' ', target.strip()).lower()


def minhash(text: str, width: int) -> list[str]:
    tokens = TOKEN_RE.findall(text)
    hashes = {
        sha(json.dumps(tokens[i:i + width], ensure_ascii=False, separators=(',', ':')))
        for i in range(len(tokens) - width + 1)
    }
    return sorted(hashes)[:8]


def read_jsonl(name: str) -> list[dict]:
    return [json.loads(line) for line in (PRIVATE / name).read_text().splitlines()]


manifest = json.loads(MANIFEST.read_text())
shadow = read_jsonl('shadow.jsonl')
historical = read_jsonl('historical.jsonl')
shadow_by_source = {}
for row in shadow:
    source = row['source']
    shadow_by_source.setdefault((source['repository'], source['commit']), row)
historical_by_source = {}
for row in historical:
    historical_by_source.setdefault((row['repository'], row['commit']), row)

entries = []
for source in sorted(set(shadow_by_source) | set(historical_by_source)):
    is_shadow = source in shadow_by_source
    row = shadow_by_source[source] if is_shadow else historical_by_source[source]
    patch = normalize_patch(row['diff'])
    entry = {
        'set': 'shadow' if is_shadow else 'historical',
        'source_commit_sha256': sha(f'{source[0]}@{source[1]}'),
        'complete_diff_sha256': sha(row['diff']),
        'normalized_patch_sha256': sha(patch),
        'changed_token_minhash': minhash(patch, 5),
    }
    if not is_shadow:
        target = normalize_target(row['message'])
        entry['normalized_target_sha256'] = sha(target)
        entry['target_token_minhash'] = minhash(target, 3)
    entries.append(entry)

old_exclusions = {
    (entry['source_commit_sha256'], entry['complete_diff_sha256'])
    for entry in manifest['hashed_commit_diff_exclusions']
}
new_exclusions = {
    (entry['source_commit_sha256'], entry['complete_diff_sha256'])
    for entry in entries
}
if old_exclusions != new_exclusions:
    raise SystemExit('derived exclusions do not match the frozen manifest')

manifest['schema_version'] = 'cnm.pierce34.shadow-manifest.v2'
manifest['counts']['leakage_exclusions'] = len(entries)
manifest['counts']['leakage_exclusions_shadow'] = sum(e['set'] == 'shadow' for e in entries)
manifest['counts']['leakage_exclusions_historical'] = sum(e['set'] == 'historical' for e in entries)
manifest['leakage_exclusions'] = {
    'algorithm': {
        'version': 'cnm.leakage-exclusion.v1',
        'patch_normalization': 'Parse unified-diff hunks; retain only lines beginning + or - inside a @@ hunk; remove the one-character change prefix; strip leading/trailing whitespace; collapse each Unicode whitespace run to one ASCII space; Unicode-lowercase each line; join lines in patch order with LF; hash UTF-8 bytes with SHA-256.',
        'target_normalization': 'Strip leading/trailing whitespace from the complete target; collapse each Unicode whitespace run to one ASCII space; Unicode-lowercase; hash UTF-8 bytes with SHA-256.',
        'tokenization': 'Apply Python regex [A-Za-z0-9_]+|[^\\s] to normalized text in order.',
        'changed_token_minhash': 'Form every consecutive 5-token shingle; encode each shingle as a compact UTF-8 JSON array with ensure_ascii=false; SHA-256 each distinct encoding; retain the lexicographically smallest 8 hashes, or all hashes when fewer than 8.',
        'target_token_minhash': 'Form every consecutive 3-token shingle; encode each shingle as a compact UTF-8 JSON array with ensure_ascii=false; SHA-256 each distinct encoding; retain the lexicographically smallest 8 hashes, or all hashes when fewer than 8.',
        'deduplication': 'Deduplicate globally by underlying canonical repository and source commit. When a commit belongs to both sets, classify it as shadow and omit target signatures.',
    },
    'counts': {
        'total': len(entries),
        'shadow': sum(e['set'] == 'shadow' for e in entries),
        'historical': sum(e['set'] == 'historical' for e in entries),
    },
    'entries': entries,
}
manifest['repository_groups'] = {
    item['canonical']: item['canonical'] for item in manifest['repository_exclusions']
}
manifest['hashes']['bundle_hash_algorithm'] = 'SHA-256 over canonical compact sorted-key UTF-8 JSON containing the frozen gate schema version and private shadow/historical file SHA-256 values; the public manifest itself is excluded.'
MANIFEST.write_text(json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2) + '\n')
print(len(entries), sum(e['set'] == 'shadow' for e in entries), sum(e['set'] == 'historical' for e in entries))

